function ratInMaze(maze) {
  const n = maze.length;
  const solution = Array.from({ length: n }, () => new Array(n).fill(0));
  const solve = (r, c) => {
    if (r === n - 1 && c === n - 1 && maze[r][c] === 1) {
      solution[r][c] = 1;
      return true;
    }
    if (r >= 0 && c >= 0 && r < n && c < n && maze[r][c] === 1 && solution[r][c] === 0) {
      solution[r][c] = 1;
      if (solve(r + 1, c)) return true;
      if (solve(r, c + 1)) return true;
      solution[r][c] = 0;
      return false;
    }
    return false;
  };
  return solve(0, 0) ? solution : null;
}

