import java.util.*;
public class RatInMaze {
    public List<String> findPaths(int[][] maze) {
        int n = maze.length;
        List<String> paths = new ArrayList<>();
        if (maze[0][0] == 1) solve(maze, 0, 0, n, "", paths, new boolean[n][n]);
        return paths;
    }
    void solve(int[][] m, int r, int c, int n, String path, List<String> paths, boolean[][] vis) {
        if (r==n-1 && c==n-1) { paths.add(path); return; }
        int[] dr={1,-1,0,0}, dc={0,0,-1,1};
        char[] dir={'D','U','L','R'};
        vis[r][c] = true;
        for (int i=0; i<4; i++) {
            int nr=r+dr[i], nc=c+dc[i];
            if (nr>=0&&nr<n&&nc>=0&&nc<n&&!vis[nr][nc]&&m[nr][nc]==1)
                solve(m, nr, nc, n, path+dir[i], paths, vis);
        }
        vis[r][c] = false;
    }
}

