#include <vector>
#include <string>
using namespace std;
int dr[]= {1, -1, 0, 0}, dc[]= {0, 0, -1, 1};
string dirs="DULR";
void solve(vector<vector<int>>&m, int r, int c, int n, string&p, vector<string>&res, vector<vector<bool>>&vis) {
    if (r==n-1&&c==n-1) {
        res.push_back(p);
        return;
    }
    vis[r][c]=true;
    for (int i=0; i<4; i++) {
        int nr=r+dr[i], nc=c+dc[i];
        if (nr>=0&&nr<n&&nc>=0&&nc<n&&!vis[nr][nc]&&m[nr][nc]) {
            p+=dirs[i];
            solve(m, nr, nc, n, p, res, vis);
            p.pop_back();
        }
    }
    vis[r][c]=false;
}
